      diagramme: '<svg viewBox="0 0 340 210" xmlns="http://www.w3.org/2000/svg"><text x="170" y="24" text-anchor="middle" font-size="12" font-weight="bold" fill="#2d2a4a">Les 5 grandes périodes de l\'histoire — clique un point !</text><line x1="20" y1="80" x2="320" y2="80" stroke="#2d2a4a" stroke-width="3"/><circle class="widget-timeline-point" cx="35" cy="80" r="9" fill="#e0574c" onclick="afficherInfobulleTimeline(this,\'Cette période a duré plus de 2 millions d\\\'années, bien plus longtemps que toutes les autres réunies !\')"/><text x="35" y="105" text-anchor="middle" font-size="9" font-weight="bold" fill="#2d2a4a">Préhistoire</text><circle class="widget-timeline-point" cx="115" cy="80" r="9" fill="#ffd166" onclick="afficherInfobulleTimeline(this,\'Les Gaulois puis les Romains vivaient sur notre territoire durant cette période, il y a plus de 2000 ans.\')"/><text x="115" y="105" text-anchor="middle" font-size="9" font-weight="bold" fill="#2d2a4a">Antiquité</text><circle class="widget-timeline-point" cx="190" cy="80" r="9" fill="#6fcf97" onclick="afficherInfobulleTimeline(this,\'Les chevaliers et les châteaux forts que tu connais peut-être des contes viennent de cette période !\')"/><text x="190" y="105" text-anchor="middle" font-size="9" font-weight="bold" fill="#2d2a4a">Moyen Âge</text><circle class="widget-timeline-point" cx="255" cy="80" r="9" fill="#6fa8dc" onclick="afficherInfobulleTimeline(this,\'L\\\'imprimerie et les grandes explorations maritimes datent de cette période.\')"/><text x="255" y="105" text-anchor="middle" font-size="8" font-weight="bold" fill="#2d2a4a">Temps modernes</text><circle class="widget-timeline-point" cx="310" cy="80" r="9" fill="#ff8fab" onclick="afficherInfobulleTimeline(this,\'Nous vivons dans cette période depuis la Révolution française de 1789 !\')"/><text x="310" y="105" text-anchor="middle" font-size="7" font-weight="bold" fill="#2d2a4a">Époque contemp.</text><rect data-role="infobulle-fond" x="15" y="118" width="310" height="50" rx="8" fill="#fff8e7" stroke="#ffd166" stroke-width="2" style="display:none;"/><text data-role="infobulle-texte" x="170" y="140" text-anchor="middle" font-size="9" fill="#2d2a4a" style="display:none;"></text><text x="20" y="190" font-size="9" fill="#2d2a4a">← Passé le plus ancien</text><text x="320" y="190" text-anchor="end" font-size="9" fill="#2d2a4a">Aujourd\'hui →</text></svg>',
