        "Sur une frise chronologique, le temps est représenté par une ligne : plus un point est situé à gauche, plus l'évènement est ancien ; plus il est à droite, plus il est récent. Pour situer un évènement, on cherche sa date, puis on le place sur la ligne, entre les deux repères déjà connus les plus proches.",
        "Mais comment les historiens savent-ils ce qui s'est passé il y a très longtemps ? Ils s'appuient sur des sources historiques, de trois sortes : les sources écrites (textes, lettres, livres), les sources orales (récits transmis de génération en génération) et les sources muettes (objets, outils, peintures, ruines de bâtiments), qui ne contiennent pas de mots mais que l'on peut observer et analyser.",
        "Par exemple, une peinture trouvée sur la paroi d'une grotte préhistorique est une source muette : elle ne raconte rien avec des mots, mais elle nous apprend énormément sur la vie des hommes qui l'ont peinte.",
