          "Le premier outil est le globe terrestre : une sphère qui représente toute la Terre, exactement comme elle est vue de l'espace. Son avantage, c'est qu'il respecte les vraies formes et les vraies tailles des continents et des océans.",
          "Le problème, c'est qu'un globe est difficile à transporter dans un cartable ! C'est pourquoi on utilise aussi le planisphère : une carte plate qui représente le monde entier, obtenue en « aplatissant » le globe. Elle déforme un peu les tailles près des pôles, mais elle est bien plus pratique à utiliser au quotidien.",
