          "La prise de vue au sol : c'est ce que tu vois quand tu es debout, avec tes yeux, au niveau du paysage. Par exemple, une photo de ton école prise depuis la cour, où tu vois la façade et l'entrée.",
          "La prise de vue oblique : elle est prise en hauteur, mais en biais, par exemple depuis une colline, un immeuble ou un avion qui regarde vers le sol de côté. Elle montre à la fois le dessus des toits et un peu les façades des bâtiments, comme sur une photo prise depuis le haut d'une tour.",
          "La prise de vue aérienne (ou vue du ciel) : elle est prise à la verticale, juste au-dessus du lieu, par un avion, un drone ou un satellite. On ne voit alors que le dessus des objets, comme sur les photos satellites qu'on utilise pour construire des cartes précises.",
