          "Au présent, ils suivent tous la même règle de terminaisons, quelle que soit la personne : -e, -es, -e, -ons, -ez, -ent. Avec le verbe chanter, cela donne : je chante, tu chantes, il/elle chante, nous chantons, vous chantez, ils/elles chantent.",
