          "Or, devant un o, le g se prononcerait « gu » (comme dans gomme) et le c se prononcerait « k » (comme dans corde) si on ne faisait rien. L'ajout du e et de la cédille permet donc de garder le même son partout : c'est une astuce de prononciation, pas une exception bizarre à apprendre sans raison !",
