          "Compare ces deux phrases : « Tous les étés, nous allions à la mer » raconte une habitude répétée (imparfait), alors que « L'été dernier, nous sommes allés à la mer » raconte un seul évènement précis (passé composé, que tu découvriras bientôt plus en détail).",
          "Regarde le schéma ci-dessous : l'imparfait ressemble à plusieurs petits points qui se répètent dans le temps, alors qu'une action ponctuelle ressemble à un seul point isolé.",
