          "N'oublie pas non plus de bien distinguer l'imparfait du passé composé : si la phrase décrit une habitude ou une situation qui dure (souvent avec 'toujours', 'tous les jours', 'chaque année'), c'est l'imparfait. Si la phrase raconte une action précise, terminée, qui s'est produite une seule fois, c'est plutôt le passé composé.",
          "Tu croiseras bientôt le passé composé et même le passé simple, deux autres temps du passé utilisés pour raconter des actions précises dans une histoire. Pour l'instant, retiens bien que l'imparfait, lui, est le temps de l'habitude et de la description.",
