          "Les énergies fossiles - le charbon, le pétrole et le gaz naturel - se sont formées en très grande profondeur, il y a des millions d'années. On dit qu'elles sont épuisables, car leurs réserves sont limitées, et elles polluent en brûlant, en rejetant des gaz qui réchauffent l'atmosphère.",
          "Les énergies renouvelables - le soleil, le vent, l'eau, la chaleur de la terre (géothermie) et le bois (biomasse) - sont dites inépuisables, car la nature les renouvelle sans cesse. Certaines maisons utilisent aussi une pompe à chaleur, un appareil qui récupère la chaleur de l'air ou du sol extérieur pour chauffer la maison. Il existe enfin l'énergie nucléaire, produite à partir d'un métal appelé uranium : elle ne rejette pas de gaz polluants en fonctionnant, mais produit des déchets radioactifs qu'il faut stocker avec beaucoup de précaution.",
