          "Un bon réflexe avant d'écrire une histoire est de lister au brouillon, dans l'ordre, les grandes étapes de ce qui va se passer, puis de choisir pour chacune le connecteur temporel le plus adapté (d'abord, ensuite, tout à coup, enfin...).",
