        "Pour parler de la météo en anglais, on pose la question : 'What's the weather like?' (Quel temps fait-il ?). On répond avec 'It's' suivi d'un adjectif de météo, par exemple : 'It's sunny.' (Il fait soleil.)",
        "Voici les principaux adjectifs météo à connaître : sunny (ensoleillé), cloudy (nuageux), rainy (pluvieux), snowy (neigeux), windy (venteux), hot (il fait chaud) et cold (il fait froid).",
        "Le petit dessin ci-dessous montre un soleil (sunny) et un nuage (cloudy) : deux temps très différents qu'on observe souvent le même jour, en été comme en hiver !",
        "Astuce : le mot anglais ressemble souvent au nom du phénomène. 'Rainy' vient de 'rain' (la pluie), 'snowy' vient de 'snow' (la neige), 'windy' vient de 'wind' (le vent).",
