        "Bonne nouvelle : contrairement à d'autres temps, les terminaisons du futur sont presque toujours les mêmes, quel que soit le verbe : -ai, -as, -a, -ons, -ez, -ont, pour je, tu, il/elle, nous, vous, ils/elles.",
